import { randomBytes } from "node:crypto";
import { SAFE_ID_PATTERN } from "../contracts";
import type { RunRef } from "../storage";

/**
 * A run ID is "<owner>/<project>/<version>", the run's folder below runs/.
 * IDs are generated by application code, never by the model.
 */

export const LOCAL_OWNER_ID = "local-dev";
export const FIRST_VERSION_ID = "v1";

export function formatRunId(run: RunRef): string {
  return `${run.ownerId}/${run.projectId}/${run.versionId}`;
}

/** Accepts "owner/project/version", optionally prefixed with "runs/" and with a trailing slash. */
export function parseRunId(text: string): RunRef | null {
  const cleaned = text.trim().replace(/^\.?\/?runs\//, "").replace(/\/+$/, "");
  const parts = cleaned.split("/");
  if (parts.length !== 3 || !parts.every((p) => SAFE_ID_PATTERN.test(p))) return null;
  const [ownerId, projectId, versionId] = parts as [string, string, string];
  return { ownerId, projectId, versionId };
}

/** New project ID from a topic title: a readable slug plus random hex, e.g. "how-the-water-cycle-works-3fa9c1". */
export function newProjectId(title: string, random: () => string = () => randomBytes(3).toString("hex")): string {
  const slug = title
    .normalize("NFKD")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, 40)
    .replace(/-+$/g, "");
  return `${slug || "project"}-${random()}`;
}
